-- Skema database DhewaMart (Cloudflare D1)
CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY, name TEXT NOT NULL, ico TEXT, sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, name TEXT NOT NULL, cat TEXT, price INTEGER NOT NULL DEFAULT 0, cost INTEGER DEFAULT 0, stock INTEGER DEFAULT 0, min INTEGER DEFAULT 5, sku TEXT DEFAULT '', ico TEXT DEFAULT '', img TEXT DEFAULT '', created_at INTEGER);
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT DEFAULT '', points INTEGER DEFAULT 0, joined INTEGER);
CREATE TABLE IF NOT EXISTS trx(id TEXT PRIMARY KEY, no TEXT, date INTEGER, sub INTEGER, disc INTEGER, pts_used INTEGER, total INTEGER, method TEXT, paid INTEGER, kasir TEXT, member_id TEXT, member_name TEXT, earn INTEGER, pts_after INTEGER, demo INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS trx_items(trx_id TEXT NOT NULL, product_id TEXT, name TEXT, cat TEXT, price INTEGER, cost INTEGER, qty INTEGER);
CREATE INDEX IF NOT EXISTS idx_trx_date ON trx(date);
CREATE INDEX IF NOT EXISTS idx_items_trx ON trx_items(trx_id);
CREATE INDEX IF NOT EXISTS idx_trx_member ON trx(member_id);
